# `fetchOrder(id: string)` Implementation

Following Step 1 first: which `tsconfig.json`/`package.json` conventions apply depends on your project. Below I assume a standard strict TypeScript ESM project (Node 20+, `"type": "module"`). Tell me your actual `package.json`/`tsconfig.json` and I'll adjust import order and dependency choices to match.

## Implementation

```ts
// src/orders/fetch-order.ts
import { z } from "zod"; // only if the project already depends on it — see note below

/**
 * Response shape from the internal orders API. Unknown until validated.
 */
const OrderSchema = z.object({
  id: z.string(),
  status: z.enum(["pending", "paid", "shipped", "cancelled"]),
  totalCents: z.number().int().nonnegative(),
  createdAt: z.string(), // ISO 8601
});

export type Order = z.infer<typeof OrderSchema>;

export interface FetchOrderOptions {
  /** Overrides the base URL (e.g. for tests). Falls back to ORDERS_API_URL. */
  baseUrl?: string;
  /** Caller-supplied cancellation, e.g. tied to an incoming request. */
  signal?: AbortSignal;
  /** Per-call timeout budget in ms. Defaults to 5_000. */
  timeoutMs?: number;
}

export class OrderNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Order not found: ${id}`);
    this.name = "OrderNotFoundError";
  }
}

export class OrderApiError extends Error {
  constructor(
    message: string,
    public readonly status: number,
    options?: { cause?: unknown },
  ) {
    super(message, options);
    this.name = "OrderApiError";
  }
}

const DEFAULT_TIMEOUT_MS = 5_000;

export async function fetchOrder(
  id: string,
  opts: FetchOrderOptions = {},
): Promise<Order> {
  // Validate external input at the boundary. `id` here may come from a route
  // handler, CLI arg, or queue message — never trust it.
  if (typeof id !== "string" || id.trim() === "") {
    throw new TypeError("fetchOrder: id must be a non-empty string");
  }

  const baseUrl = opts.baseUrl ?? process.env.ORDERS_API_URL;
  if (!baseUrl) {
    throw new Error(
      "fetchOrder: ORDERS_API_URL is not set and no baseUrl was provided",
    );
  }

  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;

  // Combine the caller's signal with a timeout signal so either can abort.
  // AbortSignal.any (Node 20.3+) avoids a bespoke race/timeout mechanism.
  const timeoutSignal = AbortSignal.timeout(timeoutMs);
  const signal = opts.signal
    ? AbortSignal.any([opts.signal, timeoutSignal])
    : timeoutSignal;

  const url = new URL(`/orders/${encodeURIComponent(id)}`, baseUrl);

  let response: Response;
  try {
    response = await fetch(url, {
      method: "GET",
      headers: { accept: "application/json" },
      signal,
    });
  } catch (cause) {
    // fetch rejects with an AbortError on timeout/cancel. Surface a message
    // that names what failed rather than letting "The operation was aborted"
    // bubble up verbatim.
    if (signal.aborted) {
      const reason =
        opts.signal?.aborted
          ? "request was cancelled by caller"
          : `request timed out after ${timeoutMs}ms`;
      throw new OrderApiError(`fetchOrder(${id}): ${reason}`, 0, { cause });
