    throw new OrderApiError(`fetchOrder(${id}): network failure`, 0, { cause });
  }

  if (response.status === 404) {
    throw new OrderNotFoundError(id);
  }

  if (!response.ok) {
    throw new OrderApiError(
      `fetchOrder(${id}): orders API returned ${response.status}`,
      response.status,
    );
  }

  // Response body is unknown until parsed and validated.
  let body: unknown;
  try {
    body = await response.json();
  } catch (cause) {
    throw new OrderApiError(
      `fetchOrder(${id}): response was not valid JSON`,
      response.status,
      { cause },
    );
