const ORDERS_API_BASE_URL =
  process.env.ORDERS_API_BASE_URL ?? "https://orders.internal";

/** Default budget for a single orders API call. Overridable per call. */
const DEFAULT_TIMEOUT_MS = 5_000;

export interface Order {
  readonly id: string;
  readonly status: "pending" | "paid" | "shipped" | "cancelled";
  readonly totalCents: number;
  readonly createdAt: string;
}

export interface FetchOrderOptions {
  /** Caller-supplied cancellation (e.g. from an incoming HTTP request). */
  readonly signal?: AbortSignal;
  /** Hard timeout per attempt. Defaults to {@link DEFAULT_TIMEOUT_MS}. */
  readonly timeoutMs?: number;
}

/** Thrown for any failure talking to the orders API. */
export class OrderApiError extends Error {
  constructor(
    message: string,
    readonly kind: "timeout" | "network" | "http" | "invalid-response",
    readonly status?: number,
    options?: { cause?: unknown },
  ) {
    super(message, options);
    this.name = "OrderApiError";
  }
}

function isOrder(value: unknown): value is Order {
  if (typeof value !== "object" || value === null) return false;
  const o = value as Record<string, unknown>;
  return (
    typeof o.id === "string" &&
    (o.status === "pending" ||
      o.status === "paid" ||
      o.status === "shipped" ||
      o.status === "cancelled") &&
    typeof o.totalCents === "number" &&
    typeof o.createdAt === "string"
  );
}

/**
 * Fetch a single order from the internal orders API.
 *
 * Never hangs indefinitely: every call is bounded by {@link FetchOrderOptions.timeoutMs}
 * (default {@link DEFAULT_TIMEOUT_MS}) in addition to any caller-supplied signal.
 *
 * @throws {OrderApiError} on timeout, network failure, non-2xx response,
 *   or a response body that fails validation.
 */
export async function fetchOrder(
  id: string,
  options: FetchOrderOptions = {},
): Promise<Order> {
  // 1. Validate the boundary input before it goes anywhere.
  if (typeof id !== "string" || id.length === 0) {
    throw new TypeError("fetchOrder: id must be a non-empty string");
  }
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(id)) {
    throw new TypeError(`fetchOrder: id has unexpected format: ${id}`);
  }

  const { signal: callerSignal, timeoutMs = DEFAULT_TIMEOUT_MS } = options;

  // 2. Compose a hard timeout that also respects caller cancellation.
  //    AbortSignal.any keeps the first-abort semantics we want.
  const timeoutSignal = AbortSignal.timeout(timeoutMs);
  const signal = callerSignal
    ? AbortSignal.any([callerSignal, timeoutSignal])
    : timeoutSignal;

  const url = new URL(`/orders/${encodeURIComponent(id)}`, ORDERS_API_BASE_URL);

  let response: Response;
  try {
    response = await fetch(url, {
      method: "GET",
      headers: { accept: "application/json" },
      signal,
    });
  } catch (cause) {
    // fetch rejects with an AbortError when the signal fires.
    const isAbort =
      cause instanceof DOMException && cause.name === "AbortError";
    const kind = isAbort
      ? timeoutSignal.aborted
        ? "timeout"
        : "network" // caller aborted
      : "network";
    throw new OrderApiError(
      `fetchOrder(${id}): ${kind} calling ${url.href}`,
      kind,
      undefined,
      { cause },
    );
  }

  // 3. Turn non-2xx into a typed error.
  if (!response.ok) {
    throw new OrderApiError(
      `fetchOrder(${id}): orders API returned ${response.status} ${response.statusText}`,
      "http",
      response.status,
    );
  }

  // 4. Parse and validate the body before trusting it.
  let body: unknown;
  try {
    body = await response.json();
  } catch (cause) {
    throw new OrderApiError(
      `fetchOrder(${id}): response body was not valid JSON`,
      "invalid-response",
      response.status,
      { cause },
    );
  }

  if (!isOrder(body)) {
    throw new OrderApiError(
      `fetchOrder(${id}): response body did not match Order shape`,
      "invalid-response",
      response.status,
    );
  }

  return body;
}
