import { setTimeout as delay } from "node:timers/promises";

/** Shape returned by the internal orders API, post-validation. */
export interface Order {
  id: string;
  status: "pending" | "paid" | "shipped" | "cancelled";
  totalCents: number;
  currency: string;
}

const DEFAULT_TIMEOUT_MS = 5_000;
const ID_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;

function readTimeoutMs(): number {
  const raw = process.env.ORDERS_API_TIMEOUT_MS;
  if (raw === undefined) return DEFAULT_TIMEOUT_MS;
  const parsed = Number(raw);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new Error(
      `Invalid ORDERS_API_TIMEOUT_MS: expected a positive number, got ${JSON.stringify(raw)}`,
    );
  }
  return parsed;
}

function readBaseUrl(): URL {
  const raw = process.env.ORDERS_API_URL;
  if (!raw) {
    throw new Error("ORDERS_API_URL is not set");
  }
  try {
    return new URL(raw);
  } catch (cause) {
    throw new Error(`Invalid ORDERS_API_URL: ${raw}`, { cause });
  }
}

function isOrder(value: unknown): value is Order {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string" &&
    (v.status === "pending" ||
      v.status === "paid" ||
      v.status === "shipped" ||
      v.status === "cancelled") &&
    typeof v.totalCents === "number" &&
    typeof v.currency === "string"
  );
}

/**
 * Fetch a single order from the internal orders API.
 *
 * Bounded by ORDERS_API_TIMEOUT_MS (default 5s) so a slow upstream cannot
 * hang the caller indefinitely. Pass an AbortSignal to cancel earlier.
 */
export async function fetchOrder(
  id: string,
  signal?: AbortSignal,
): Promise<Order> {
  // Boundary validation — reject before touching the network.
  if (typeof id !== "string" || !ID_PATTERN.test(id)) {
    throw new Error(`Invalid order id: ${JSON.stringify(id)}`);
  }

  const baseUrl = readBaseUrl();
  const timeoutMs = readTimeoutMs();
  const url = new URL(`/orders/${encodeURIComponent(id)}`, baseUrl);

  // Bound the call: the smaller of the caller's signal and our own budget.
  const timeoutSignal = AbortSignal.timeout(timeoutMs);
  const combined = signal
    ? AbortSignal.any([signal, timeoutSignal])
    : timeoutSignal;

  let response: Response;
  try {
    response = await fetch(url, {
      method: "GET",
      headers: { accept: "application/json" },
      signal: combined,
    });
  } catch (cause) {
    // Distinguish our timeout from a caller-triggered abort from other
    // network failures, so the caller can decide whether to retry.
    if (timeoutSignal.aborted && !signal?.aborted) {
      throw new Error(
        `Timed out after ${timeoutMs}ms fetching order ${id}`,
        { cause },
      );
    }
    if (signal?.aborted) {
      throw new Error(`Aborted while fetching order ${id}`, { cause });
    }
    throw new Error(`Network error fetching order ${id}`, { cause });
  }

  if (response.status === 404) {
    throw new Error(`Order not found: ${id}`);
  }
  if (!response.ok) {
    throw new Error(
      `Orders API returned ${response.status} ${response.statusText} for order ${id}`,
    );
  }

  // Validate the response before it crosses into business logic.
  let body: unknown;
  try {
    body = await response.json();
  } catch (cause) {
    throw new Error(`Orders API returned invalid JSON for order ${id}`, {
      cause,
    });
  }
  if (!isOrder(body)) {
    throw new Error(
      `Orders API returned an unexpected payload for order ${id}`,
    );
  }

  return body;
}
